# -*- coding: utf-8 -*-

from taf.fdsw.rc.clients.http.http_client import RCHttpClient
from taf.fdsw.rc.interfaces.FDSW19A.fdsw import FDSW19A


class FDSW20A(FDSW19A):
    API_VERSION = "1.1"
    API_SCHEMA_VERSION = "2.0"
    VERSION_NAME = 'FDSW20A'
    _client = None

    def __init__(self, ip_address, port, username, password, secure=True):
        super(FDSW20A, self).__init__(ip_address=ip_address, port=port, username=username, password=password,
                                      secure=secure)
        self._client = RCHttpClient(
            ip_address=ip_address,
            port=port,
            username=username,
            password=password,
            secure=secure,
            api_version=self.API_VERSION,
            api_schema_version=self.API_SCHEMA_VERSION
        )

        self._client.connect()
